def distinct_subseq(S):
    MOD = 10**9 + 7
    memo = {}

    def dp(i):
        if i == len(S):
            return 1
        if i in memo:
            return memo[i]
        memo[i] = dp(i + 1)
        for j in range(i + 1, len(S)):
            if S[j] == S[i]:
                memo[i] = (memo[i] + dp(j)) % MOD
        return memo[i]

    return dp(0)
